var total = Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_24_22");
var netAmount = Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_24_45_1");

// fields to sum up
var fields = [];
fields.push(Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_24_23"));

run();
function run() {

    if (!total)
        return;

    if (Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_24_45")) {
        var TaxRatesRows = Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_24_45").Instances;
        for (var i = 0; i < TaxRatesRows.length; i++) {
            var net = TaxRatesRows[i].GetChild(netAmount.Id);
            fields.push(net);
        }
    }
    var totalAmount = (total.Value && total.Value.Amount) ? total.Value.Amount : 0;
    var sum = 0;

    var comparisonNeeded = false;
    //= show error only if at least one subfield and has data 

    for (var i = 0; i < fields.length; i++) {
        if (fields[i] && fields[i].Text != "") {
            comparisonNeeded = true;
            if (fields[i].Value && fields[i].Value.Amount)
                sum = sum + fields[i].Value.Amount;
        }
    }
    if (total.Text == "" && comparisonNeeded && !(total.IsConfirmed)) {
        total.Value = getRoundedValue(sum);
    } else if (Math.abs(sum - totalAmount) > 0.02) {

        suggest(total, sum);
        var allValuesConfirmed = true;

        for (var i = 0; i < fields.length; i++) {
            if (!fields[i])
                continue;
            if (!fields[i].Value || !fields[i].Value.Amount)
                suggest(fields[i], totalAmount - sum);
            else
                suggest(fields[i], fields[i].Value.Amount + totalAmount - sum);

            if (!fields[i].IsConfirmed)
                allValuesConfirmed = false;
        }
        if (comparisonNeeded && !(total.IsConfirmed && allValuesConfirmed))
            Context.CheckSucceeded = false;

    }

    function getRoundedValue(value) {
        return Math.round(value * 100) / 100;
    }

    function suggest(field, value) {
        if (value == NaN)
            return;

        var roundedValue = getRoundedValue(value);

        if (field.DataType == DataType.Number
            && (
                (!field.Value && (value || (field.Text && field.Text != 0))
                    || Math.abs(field.Value - value) > 0.01)
            ))
            field.AddSuggestion(roundedValue.toString());

        if (field.DataType == DataType.Amount
            && (
                ((!field.Value || !field.Value.Amount) && (value || (field.Text && field.Text != 0)))
                || (field.Value && Math.abs(field.Value.Amount - value) > 0.01))
        )
            field.AddSuggestion(roundedValue.toString());
    }
}

