var total =  Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_40");
var netTotal =  Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_24_22");
var column = Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_51_2");
var checkmark = Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_51_3");

if (total && total.Value && Context.GetField ("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_51") && column) 
{   
    var totalAmount = (total.Value && total.Value.Amount) ? total.Value.Amount : 0;
    var netTotalAmount = (netTotal.Value && netTotal.Value.Amount) ? netTotal.Value.Amount : 0;
    var sum = 0;  

    var comparisonNeeded = false;     
    //= show error only if at least one subfield is visible and has data 

    var rows = Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_51").Instances;

    for (var i=0; i<rows.length; i++) 
    {      
        var rowtotal = rows[i].GetChild(column.Id);        

        if (rowtotal  && rowtotal.IsVisible && rowtotal.Text)   
        {   
          comparisonNeeded = true;       
        if (rowtotal.Value && rowtotal.Value.Amount)
                sum = sum +  rowtotal.Value.Amount; 
        } 
    }

    if (Math.abs(sum - totalAmount) > 0.02 && Math.abs(sum - netTotalAmount) > 0.02)    
    {    
        if (sum!=0) {
            suggest(total, sum); 
            suggest(netTotal, sum);  
        }   

        var allColumnValuesConfirmed = true;

        for (var i=0; i<rows.length; i++) 
        {      
            var rowtotal = rows[i].GetChild(column.Id); 
            var isChecked = rows[i].GetChild(checkmark.Id).Value;

            if (!rowtotal.Value || ! rowtotal.Value.Amount)
                suggest(rowtotal, totalAmount-sum);  
            else     
                suggest(rowtotal, rowtotal.Value.Amount + totalAmount - sum); 

            if (!rowtotal.IsConfirmed && !isChecked)
                allColumnValuesConfirmed = false;
        }   

    if (comparisonNeeded &&  !(total.IsConfirmed && allColumnValuesConfirmed))
        Context.CheckSucceeded = false;
    }   
}

function getRoundedValue(value) {
    return Math.round(value * 100) / 100;
}

function suggest (field, value) {
    if (value==NaN)
        return;

    var roundedValue = getRoundedValue(value);

    if (field.DataType == DataType.Number 
        && (
        (!field.Value && (value || (field.Text && field.Text != 0)) 
        || Math.abs(field.Value-value) > 0.01)
        ))
        field.AddSuggestion(roundedValue.toString());

    if (field.DataType == DataType.Amount 
        && (
        ((!field.Value || !field.Value.Amount) && (value || (field.Text && field.Text != 0)))
        || (field.Value && Math.abs(field.Value.Amount-value) > 0.01))
        )
        field.AddSuggestion(roundedValue.toString());
}

