function run() {

    if (!mainCurrencyField)
        return;



    var tableCurrencyValue = "";
    Context.ErrorMessage="Currency does not match allowed values. "; 

    ApplySafeModifications (mainCurrencyField);
    CopyCurrencyFromLineItems (); //fill out main currency field from table currencies
    DetectNationalCurrency();
    CopyCurrencyToLineItems (); //copy main currency to table cells 

    mainCurrencyField = Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_41"); 
    tableCurrencyValue = "";
    CheckInvoiceCurrencyValue(); //check main currency against allowed values, add suggestions
    CheckLineItemsCurrencyValue(); //check table currencies against allowed values, add suggestions
    Context.ErrorMessage = Context.ErrorMessage.trim();

    function CopyCurrencyFromLineItems () {  
        if (!lineItems 
            || (lineItemsRows.length==1 && lineItemsRows[0].IsEmpty)) 
            return;

        if (mainCurrencyField && !mainCurrencyField.IsConfirmed && ! mainCurrencyField.HasRegion  
            && (!mainCurrencyField.Value || allowedCurrencyValues.indexOf(mainCurrencyField.Value)<0)) 
        { 
             for (var i = 0; i < currencyColumn.length; i++) 
            {
                var LIcurrency =  currencyColumn[i];
                ApplySafeModifications (LIcurrency);
                if (allowedCurrencyValues.indexOf(LIcurrency.Value)>=0) 
                {
                    if(!tableCurrencyValue) 
                        tableCurrencyValue = LIcurrency.Value; 

                    //if there is more than one legitimate currency in the table, abort             
                    else if (tableCurrencyValue != LIcurrency.Value)               
                        return;  
                }
            }
            if (tableCurrencyValue) 
                mainCurrencyField.Value = tableCurrencyValue;
    } 
    }

    function CurrencyByCountry(country){
    for (var i=0; i <country_currency.length; i++ ) 
        if (country_currency[i][0] == country) 
        {
            return country_currency[i][1];
        }
        return "";
    }

    function DetectNationalCurrency() {    
        if (buyerCountry && buyerCountry.Value 
        && vendorCountry && vendorCountry.Value
        &&  !mainCurrencyField.Value)
            var buyerCurrency=CurrencyByCountry(buyerCountry.Value);
            var vendorCurrency=CurrencyByCountry(vendorCountry.Value);
            if (buyerCurrency==vendorCurrency &&  buyerCurrency!="")
            {
                mainCurrencyField.Value = buyerCurrency;                    
            }     
    }  

    function CopyCurrencyToLineItems () {
        if (!lineItems || 
            (lineItemsRows.length==1 && lineItemsRows[0].IsEmpty)) 
            return;

        var mainCurrency = ""; 
        if (mainCurrencyField && mainCurrencyField.Value 
            && allowedCurrencyValues.indexOf(mainCurrencyField.Value)>=0)
            mainCurrency = mainCurrencyField.Value;  

        for (var i=0; i< currencyColumn.length; i++) 
        {  
            var LIcurrency =  currencyColumn[i];      
            if (LIcurrency && !LIcurrency.IsConfirmed && mainCurrency 
                && (!LIcurrency.Value || allowedCurrencyValues.indexOf(LIcurrency.Value)<0)) 
                LIcurrency.Value = mainCurrency;  
        }   
    }

    function CheckInvoiceCurrencyValue() { 
        if (mainCurrencyField  && (!mainCurrencyField.Value  || allowedCurrencyValues.indexOf(mainCurrencyField.Value)<0)) { 
            Context.CheckSucceeded = false; 
            Context.ErrorMessage += "\n Main Currency;"; 
            for (var i=0; i< currencyValuesForSuggestions.length; i++) {
                mainCurrencyField.AddSuggestion(currencyValuesForSuggestions[i]); 
            } 
        } 
    }  

    function CheckLineItemsCurrencyValue() { 
        if (!lineItems || 
            (lineItemsRows.length==1 && lineItemsRows[0].IsEmpty)) 
            return;

        for (var i=0; i< currencyColumn.length; i++) 
        {   
            var LIcurrency =  currencyColumn[i];     
            if (LIcurrency && !LIcurrency.IsConfirmed   
                && (!LIcurrency.Value || allowedCurrencyValues.indexOf(LIcurrency.Value)<0)) 
            { 
                if (allowedCurrencyValues.indexOf(LIcurrency.Value)<0) 
                { 
                    for (var j=0; j<currencyValuesForSuggestions.length; j++)  
                        LIcurrency.AddSuggestion(currencyValuesForSuggestions[j]);                        
                    if (LIcurrency.Value) 
                    { 
                        Context.CheckSucceeded = false;
                        Context.ErrorMessage += "\n LI Currency " +  (i+1)+";"; 
                    }  
                }       
            }  
        }    
    }

    function ApplySafeModifications (currencyField) {      

        if (!currencyField || !currencyField.Value)
            return;

        var currencyValue = currencyField.Value.trim().replace(/\s/g, '').replace(/\./g, '').toUpperCase(); 

        if (currencyValue.substring(currencyValue.length-3) == "(S)")
            currencyValue = currencyValue.substring(0, currencyValue.length-3);
        for (var i=0; i < symbol_currency.length; i++ ) 
        {
            if (symbol_currency[i][0].indexOf(currencyValue)>-1) 
            {
                if (symbol_currency[i][1].length == 1) {
                    currencyValue = symbol_currency[i][1][0];
                    break;
                }            
                else if ((buyerCountry && buyerCountry.Value)
                    || (vendorCountry && vendorCountry.Value)) 
                {
                var buyerCurrency = "";
                var vendorCurrency = "";

                var entry = country_currency.filter(e => e[0]== buyerCountry.Value)
                if (entry && entry.length>0 && entry[0].length>0 && entry[0][1]) 
                    buyerCurrency = entry[0][1];
                entry = country_currency.filter(e => e[0]== vendorCountry.Value)
                if (entry && entry.length>0 && entry[0].length>0 && entry[0][1]) 
                    vendorCurrency = entry[0][1];

                if (buyerCurrency 
                    && buyerCurrency == vendorCurrency 
                    && symbol_currency[i][1].indexOf(buyerCurrency)>-1)
                    currencyValue =  buyerCurrency;
                else if (buyerCurrency                  
                    && symbol_currency[i][1].indexOf(buyerCurrency)>-1
                    && symbol_currency[i][1].indexOf(vendorCurrency)<0)
                    currencyValue =  buyerCurrency; 
                else if (vendorCurrency                  
                    && symbol_currency[i][1].indexOf(vendorCurrency)>-1
                    && symbol_currency[i][1].indexOf(buyerCurrency)<0)
                    currencyValue =  vendorCurrency;

                if (allowedCurrencyValues.indexOf(currencyValue)<0) 
                {
                    if (buyerCurrency)
                        currencyValuesForSuggestions.push(buyerCurrency);
                    if (vendorCurrency)
                        currencyValuesForSuggestions.push(vendorCurrency);
                    if (symbol_currency[i][0].indexOf("$")>-1)
                        currencyValuesForSuggestions.push("USD");    
                }           
                }
                else if (allowedCurrencyValues.indexOf(currencyValue)<0) 
                    symbol_currency[i][1].forEach(cur => {currencyValuesForSuggestions.push(cur)});                          
            }
        }

        if (allowedCurrencyValues.indexOf(currencyValue)>-1) 
        {
            currencyField.Value = currencyValue;
            return;
        }
    }
}

