var itemizedtable = false;

var quantityField = Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_53_3");
var unitPriceField = Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_53_4");    
var discountField = Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_53_17");
var netTotalField = Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_53_6");
var taxRateField = Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_53_14");
var taxField = Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_53_18");
var totalField = Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_53_7");

run();
function run() {

    if (!(quantityField && unitPriceField && discountField && netTotalField && taxRateField && taxField && totalField))
        return;    



    if (quantityField.Text || unitPriceField.Text) 
        itemizedtable = true;

    var quantity = (quantityField.Value) ? quantityField.Value : 0;
    var unitPrice = (unitPriceField.Value && unitPriceField.Value.Amount) ? unitPriceField.Value.Amount : 0;
    var discount = (discountField.Value && discountField.Value.Amount) ? discountField.Value.Amount : 0;
    var netTotal = (netTotalField.Value && netTotalField.Value.Amount) ? netTotalField.Value.Amount : 0;
    var taxRate = (taxRateField.Value) ? taxRateField.Value : 0;
    var taxPreliminary = (taxField.Value && taxField.Value.Amount) ? taxField.Value.Amount : 0;
    var total = (totalField.Value && totalField.Value.Amount) ? totalField.Value.Amount : 0;

    var netResult = (quantity*unitPrice)-discount;
    removePercentSign();
    var tax = taxPreliminary;
    if (!tax)
        tax = netResult * taxRate / 100;
    if (!tax)
        tax = netTotal * taxRate / 100;   

    var result = netResult+tax;   

    if ((itemizedtable && (!netTotalField.Text && !total)) 
    || (itemizedtable && netTotalField.Text  && Math.abs(netResult-netTotal)>0.01)
    || (itemizedtable && totalField.Text && Math.abs(result-total)>0.01) 
    || (totalField.Text && netTotalField.Text && Math.abs(netTotal + tax-total)>0.01) 
    || (itemizedtable && taxField.Text && taxRateField.Text && Math.abs ((netResult * taxRate / 100) - taxPreliminary) > 0.01)  
    )
        Context.CheckSucceeded = false;


    //quantity
    if (unitPrice)  
    {   
        if (netTotal)
            suggest(quantityField, (netTotal+discount) / unitPrice);  
        if (total)
            suggest(quantityField, (total - tax + discount) / unitPrice);
    }  

    //unit price
    if (quantity) 
    {    
        if (netTotal)     
            suggest(unitPriceField, (netTotal+discount) / quantity);   
        if (total)
            suggest(unitPriceField, (total - tax + discount) / quantity); 
    }

    //discount  
    var discrepancy = (quantity*unitPrice)-netTotal;
    if (netTotal && discrepancy>0)
        suggest(discountField, discrepancy); 
    discrepancy = (quantity*unitPrice)-total+tax;
    if (total && discrepancy>0)            
        suggest(discountField, discrepancy); 

    //net total
    suggest (netTotalField, netResult); 
    if (total)
        suggest (netTotalField, total - tax);    

    //total      
    suggest (totalField, result); 
    if (netTotal)
        suggest (totalField, netTotal + tax);    

    //tax
    if (total)
        suggest(taxField, total-netResult);
    if (total && netTotal)
        suggest(taxField, total-netTotal);
    if (taxRate) 
    {
        suggest(taxField, netResult * taxRate / 100);
        if (netTotal)
            suggest(taxField, netTotal * taxRate / 100);
    }

    //tax rate  
    if (netResult)
    suggest(taxRateField, (taxPreliminary/netResult)*100);
    if (netTotal)
        suggest(taxRateField, (taxPreliminary/netTotal)*100);
    if (total && netResult)
        suggest(taxRateField, ((total-netResult)/netResult)*100);
    if (total && netTotal)
        suggest(taxRateField, ((total-netTotal)/netTotal)*100);

    function removePercentSign() {
        if (taxRateField.Value && taxRateField.Text.indexOf ("%")>-1) 
        {
            var newValue = taxRateField.Value;
            taxRateField.Value = 0;
            taxRateField.Value = newValue;
        }
    } 

    function getRoundedValue(value) {
        return Math.round(value * 100) / 100;
    }

    function suggest (field, value) {
        if (value==NaN)
            return;

        var roundedValue = getRoundedValue(value);

        if (field.DataType == DataType.Number 
            && (
            (!field.Value && (value || (field.Text && field.Text != 0)) 
            || Math.abs(field.Value-value) > 0.01)
            ))
            field.AddSuggestion(roundedValue.toString());

        if (field.DataType == DataType.Amount 
            && (
            ((!field.Value || !field.Value.Amount) && (value || (field.Text && field.Text != 0)))
            || (field.Value && Math.abs(field.Value.Amount-value) > 0.01))
            )
            field.AddSuggestion(roundedValue.toString());
    }
}

