var total = Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_24_21");

run();
function run() {

    if (!total)
        return;

    var totalAmount = (total.Value && total.Value.Amount) ? total.Value.Amount : 0;
    var sum = 0;

    var comparisonNeeded = false;
    //=show error only if at least one subfield has data 

    if (Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_24_45")) {

        var taxesRows = Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_24_45").Instances;

        for (var i = 0; i < taxesRows.length; i++) {
            var tax = taxesRows[i].GetChild(TaxAmount.Id);
            var net = taxesRows[i].GetChild(NetAmount.Id);
            var rate = taxesRows[i].GetChild(TaxRate.Id);

            var netValue = (net.Value && net.Value.Amount) ? net.Value.Amount : 0;
            var taxValue = (tax.Value && tax.Value.Amount) ? tax.Value.Amount : 0;
            var rateValue = (rate.Value) ? rate.Value : 0;


            removePercentSign();
            suggestValues();
            checkMath();
            sumTotalAmounts();


            function removePercentSign() {
                if (rate.Value && rate.Text.indexOf("%") > -1) {
                    var newValue = rate.Value;
                    rate.Value = 0;
                    rate.Value = newValue;
                }
            }

            function suggestValues() {

                if (!tax.Value && rateValue != 0 && netValue != 0)
                    suggest(tax, rate.Value / 100 * net.Value.Amount);

                if (!net.Value && rateValue != 0 && taxValue != 0)
                    suggest(net, tax.Value.Amount / rate.Value * 100);

                if (!rate.Value && netValue != 0 && taxValue != 0)
                    suggest(rate, taxValue / netValue * 100);
            }

            function checkMath() {
                if (rate.Value
                    && net.Value && net.Value.Amount
                    && tax.Value && tax.Value.Amount) {
                    var result = rateValue / 100 * netValue;
                    if (Math.abs(result - (Math.abs(taxValue))) > 0.02) {
                        if (!(rate.IsConfirmed && tax.IsConfirmed && net.IsConfirmed))
                            Context.CheckSucceeded = false;

                        suggest(tax, result);

                        if (netValue != 0)
                            suggest(rate, taxValue / netValue * 100);

                        if (rateValue != 0)
                            suggest(net, taxValue / rateValue * 100);
                    }
                }
            }

            function sumTotalAmounts() {
                if (tax && tax.Text != "")
                    comparisonNeeded = true;
                if (tax.Value && tax.Value.Amount)
                    sum = sum + tax.Value.Amount;
            }
        }
        //if totalTax is empty, fill it with sum of Taxes; if some tax field is absent, suggest the value
        if (total.Text == "" && comparisonNeeded && !(total.IsConfirmed)) {
            total.Value = getRoundedValue(sum);
        }
        else if (Math.abs(sum - totalAmount) > 0.02) {

            suggest(total, sum);
            var allValuesConfirmed = true;

            for (var i = 0; i < taxesRows.length; i++) {
                var tax = taxesRows[i].GetChild(TaxAmount.Id);
                if (!tax)
                    continue;
                if (!tax.Value || !tax.Value.Amount)
                    suggest(tax, totalAmount - sum);
                else
                    suggest(tax, tax.Value.Amount + totalAmount - sum);

                if (!tax.IsConfirmed)
                    allValuesConfirmed = false;
            }

            if (comparisonNeeded && !(total.IsConfirmed && allValuesConfirmed))
                Context.CheckSucceeded = false;

        }
    }

    function getRoundedValue(value) {
        return Math.round(value * 100) / 100;
    }

    function suggest(field, value) {
        if (value == NaN)
            return;

        var roundedValue = getRoundedValue(value);

        if (field.DataType == DataType.Number
            && (
                (!field.Value && (value || (field.Text && field.Text != 0))
                    || Math.abs(field.Value - value) > 0.01)
            ))
            field.AddSuggestion(roundedValue.toString());

        if (field.DataType == DataType.Amount
            && (
                ((!field.Value || !field.Value.Amount) && (value || (field.Text && field.Text != 0)))
                || (field.Value && Math.abs(field.Value.Amount - value) > 0.01))
        )
            field.AddSuggestion(roundedValue.toString());
    }
}

