var orderGroup = Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_51");
var numberColumn = Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_51_1");
var checkmarkColumn = Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_51_3");

var lineItems = Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_53");
var liRows = lineItems.Instances;
var liNumberColumn = Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_53_8");
var liItemIdColumn = Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_53_26");

run();

function run() {

    if (!(orderGroup && orderGroup.Instances.length>0 && numberColumn && checkmarkColumn
            && lineItems && lineItems.Instances.length>0 && liNumberColumn && liItemIdColumn))
        return;

    var purchaseOrders = orderGroup.Instances;

    for (var i=0; i<purchaseOrders.length; i++) 
    {      
        var orderNumberField = purchaseOrders[i].GetChild(numberColumn.Id);        
        var isChecked = purchaseOrders[i].GetChild(checkmarkColumn.Id).Value;

        if (!orderNumberField.Value || isChecked)
            continue;

        checkLineItemsIds(orderNumberField.Value); 
    }
}

function checkLineItemsIds(orderNumber) {
    var previousIds = [];

    for (var j=0; j<liRows.length; j++) 
    {       
        var liId = liRows[j].GetChild(liItemIdColumn.Id).Value;
        var liOrderNo = liRows[j].GetChild(liNumberColumn.Id).Value;

        if (!liOrderNo || liOrderNo != orderNumber)
            continue;
        if (liId) 
        {       
            if (previousIds.indexOf(liId)>-1)  
            {
                Context.CheckSucceeded  = false;
                Context.ErrorMessage = "Several Line Items from the same order '" + orderNumber + "' (e.g. line " + (j+1) +") have the same order item id: " + liId;
            }
            previousIds.push(liId);
        } 
    }    
}

fa33bbb4-127c-4664-ae38-07b973772919.script:
var tableON = Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_53_8");
var fieldON = Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_51_1");
var table = Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_53");
var poField = Context.GetField("FC_f8a9a136_2116_4002_b87d_90ef2d139d60_51");

var tableONs = [];
if (table && poField) {
   copyONtoTable(tableONs); 
}

function copyONtoTable(tableONs) {   
    if (table.Instances.length == 0 || table.Instances[0].IsEmpty)
        return;

    var poRows = poField.Instances;  

    for (var i = 0; i <poRows.length; i++) { 
        var poON = poRows[i].GetChild(fieldON.Id);  
        if (poON && poON.Value && tableONs.indexOf(poON.Value)==-1) {
            tableONs.push(poON.Value);
        }
    }

    if (tableONs.length==0 ||tableONs.length>1)
        return;

    var lineItemsRows = table.Instances;

    for (var i = 0; i <lineItemsRows.length; i++) { 
        var LineItemsON = lineItemsRows[i].GetChild(tableON.Id);  
        if (LineItemsON && LineItemsON.Value && tableONs.indexOf(LineItemsON.Value)==-1) {
            tableONs.push(LineItemsON.Value);
        }
    }
    for (var i = 0; i <lineItemsRows.length; i++) { 
        var LineItemsON = lineItemsRows[i].GetChild(tableON.Id);

        if (LineItemsON && !LineItemsON.Value && tableONs.length==1) {
            LineItemsON.Value = tableONs[0];
        }  
    }    
}
